function AbutronV7SortTrades20261028(rows,lifecycle,query,sortKey,sortDirection){
  const numericKeys=["volume","open_price","close_price","net_pnl"];
  const dateKeys=["opened_at","closed_at"];
  const searchable=["broker_ticket","symbol","direction","volume","open_price","close_price","lifecycle","opened_at","closed_at","net_pnl"];
  const needle=String(query||"").trim().toLowerCase();
  const visible=rows.filter(t=>(lifecycle==="ALL"||t.lifecycle===lifecycle)
    &&(!needle||searchable.some(key=>String(t[key]??"").toLowerCase().includes(needle))));
  const direction=sortDirection==="ASC"?1:-1;
  return visible.sort((a,b)=>{
    const av=a[sortKey],bv=b[sortKey];
    const aMissing=av==null||av==="",bMissing=bv==null||bv==="";
    if(aMissing||bMissing){return aMissing===bMissing?0:aMissing?1:-1;}
    let compare=0;
    if(numericKeys.includes(sortKey)){
      const an=Number(av),bn=Number(bv);
      compare=Number.isFinite(an)&&Number.isFinite(bn)?an-bn:String(av).localeCompare(String(bv));
    }else if(dateKeys.includes(sortKey)){
      const an=Date.parse(String(av)),bn=Date.parse(String(bv));
      compare=Number.isFinite(an)&&Number.isFinite(bn)?an-bn:String(av).localeCompare(String(bv));
    }else compare=String(av).localeCompare(String(bv),undefined,{numeric:true,sensitivity:"base"});
    return compare===0?String(a.id??"").localeCompare(String(b.id??"")):direction*compare;
  });
}


