/* V7 verified customer notification acknowledgement, no financial effects. */
function AbutronNotifications20261023({token:userToken}) {
 const [items,setItems]=zl.useState([]);
 const [state,setState]=zl.useState("loading");
 const [busy,setBusy]=zl.useState(false);
 const [message,setMessage]=zl.useState("");
 zl.useEffect(()=>{
  let active=true;
  const stop=new AbortController();
  async function load(){
   try {
    const response=await fetch("/api/v1/notifications",{
     cache:"no-store",headers:{Authorization:"Bearer "+userToken},signal:stop.signal
    });
    if(!response.ok)throw new Error("NOTIFICATION_READ_UNAVAILABLE");
    const data=await response.json();
    if(!Array.isArray(data)||data.length>100)throw new Error("BAD_NOTICE_SHAPE");
    if(active){setItems(data);setState("verified");}
   } catch{if(active){setItems([]);setState("unavailable");}}
  }
  load();
  return()=>{active=false;stop.abort();};
 },[userToken]);
 async function markRead(n){
  if(busy||!n||n.read_at)return;
  const id=String(n.id??"");
  if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)){
   setMessage("Notification identifier invalid.");return;
  }
  setBusy(true);setMessage("");
  try{
   const response=await fetch("/api/v1/notifications/"+id+"/read",{
    method:"PATCH",headers:{Authorization:"Bearer "+userToken,"Content-Type":"application/json"}
   });
   if(!response.ok)throw new Error("NOTIFICATION_ACK_FAILED");
   const confirmed=await response.json();
   if(String(confirmed.id)!==id||!confirmed.read_at)throw new Error("INVALID_CONFIRMATION");
   setItems(old=>old.map(x=>String(x.id)===id?{...x,read_at:confirmed.read_at}:x));
  }catch{setMessage("Unable to mark this notification read. Nothing changed in the display.");}
  finally{setBusy(false);}
 }
 return s.jsxs("section",{className:"panel",children:[
  s.jsx("h2",{children:"Notifications"}),
  s.jsx("p",{className:"subtle",children:"Your verified account notifications. Marking a notification read changes only its acknowledgement timestamp; trading, billing and licensing remain locked."}),
  state==="loading"&&s.jsx("p",{children:"Checking notifications…"}),
  state==="unavailable"&&s.jsx("p",{className:"danger-text",children:"Notification data unavailable. No records are assumed."}),
  message&&s.jsx("p",{className:"danger-text",children:message}),
  state==="verified"&&items.map(n=>s.jsxs("article",{className:"notice",children:[
   s.jsx("strong",{children:String(n.title||n.status||"Notification")}),
   s.jsx("p",{children:String(n.body||n.created_at||"")}),
   n.read_at?s.jsx("small",{children:"Read"}):
    s.jsx("button",{className:"outline-button",disabled:busy,onClick:()=>markRead(n),children:busy?"Updating…":"Mark read"})
  ]},String(n.id))),
  state==="verified"&&items.length===0&&s.jsx("p",{className:"empty",children:"No notifications found."})
 ]});
}



