const V7_KRONOS_TF=["M1","M3","M5","M15","M30","H1","H4","D1"];
const V7_KRONOS_SYMBOLS=["R_10","R_25","R_50","R_75","R_100","CRASH150N","CRASH300N","CRASH600","CRASH1000","BOOM150N","BOOM300N","BOOM600","BOOM1000"];
const V7_CANDLE_MIN={M1:1,M3:3,M5:5,M15:15,M30:30,H1:60,H4:240,D1:1440};
function V7KronosEightFrame({token}){
 const [broker,setBroker]=zl.useState("Deriv"),[symbol,setSymbol]=zl.useState("R_10");
 const [report,setReport]=zl.useState(null),[feedState,setFeedState]=zl.useState("loading"),[tick,setTick]=zl.useState(Date.now());
 const groups={"Deriv":V7_KRONOS_SYMBOLS,
  "IC Markets":["XAUUSD","BTCUSD","EURUSD","GBPUSD","USDJPY","AUDUSD","US100","US30","SP500","GER40","USOIL","USDCHF","NZDUSD"],
  "FP Markets":["XAUUSD","BTCUSD","EURUSD","GBPUSD","USDJPY","AUDUSD","US100","US30","SP500","GER40","USOIL","USDCHF","NZDUSD"]};
 zl.useEffect(()=>{const timer=window.setInterval(()=>setTick(Date.now()),1000);return()=>window.clearInterval(timer)},[]);
 zl.useEffect(()=>{
  let active=true,loading=false;
  const controller=new AbortController;
  setReport(null);
  setFeedState(broker==="Deriv"?"loading":"broker_not_connected");
  if(broker!=="Deriv")return()=>{active=false;controller.abort()};
  async function load(){
   if(loading)return;
   loading=true;
   try{
    const resp=await fetch("/api/v1/research/deriv/closed-candles?symbol="+encodeURIComponent(symbol),{
      headers:{Authorization:"Bearer "+token},cache:"no-store",signal:controller.signal});
    if(!resp.ok)throw Error("BROKER_HISTORY_FAILED");
    const d=await resp.json();
    if(d.schema!=="ABUTRON_DERIV_NATIVE_CLOSED_CANDLE_RESEARCH_V1"||
       d.source!=="DERIV_PUBLIC_CANDLE_HISTORY_NO_CUSTOMER_AUTH"||
       d.symbol!==symbol||d.market!=="DERIV_PUBLIC_OPTIONS_MARKET_NOT_MT5"||
       d.orders_authorized!==false||d.customer_mt5_account_linked!==false||
       d.kronos_strategy_signal_certified!==false||
       !Array.isArray(d.rows)||d.rows.length!==8||
       !V7_KRONOS_TF.every((tf,i)=>d.rows[i].timeframe===tf)||
       !d.rows.every(r=>r.broker_public_candle_verified===true&&r.is_candle_closed===true&&
         ["BUY","SELL","NEUTRAL"].includes(r.candle_bias)&&
         r.basis==="CLOSE_MINUS_OPEN_ONLY"&&
         Number.isFinite(Date.parse(r.candle_closed_utc))&&
         Number.isFinite(Number(r.open))&&Number.isFinite(Number(r.close))))throw Error("UNVERIFIED_BROKER_CANDLES");
    if(active){setReport(d);setFeedState("verified")}
   }catch(e){if(active&&!controller.signal.aborted){setReport(null);setFeedState("unavailable")}}
   finally{loading=false}
  }
  load();const timer=window.setInterval(load,15000);
  return()=>{active=false;window.clearInterval(timer);controller.abort()}
 },[token,broker,symbol]);
 function countdown(tf){
  const period=V7_CANDLE_MIN[tf]*60000;
  const next=(Math.floor(tick/period)+1)*period,sec=Math.ceil((next-tick)/1000);
  return tf+" close in "+Math.floor(sec/60)+"m "+String(sec%60).padStart(2,"0")+"s";
 }
 function candle(tf){
  const r=report?.rows.find(x=>x.timeframe===tf);
  if(!r)return null;
  const period=V7_CANDLE_MIN[tf]*60000,age=tick-Date.parse(r.candle_closed_utc);
  return Number.isFinite(age)&&age>=-2000&&age<=period+70000?r:null
 }
 return s.jsxs("section",{className:"panel kronos-research-panel",children:[
  s.jsxs("div",{className:"v7-section-heading",children:[s.jsx("h2",{children:"Kronos Research · Broker Candle Analysis"}),
   s.jsx("span",{className:"v7-pill",children:"8 native candle periods"})]}),
  s.jsx("p",{className:"subtle",children:"Actual Deriv broker-public closed OHLC candles. BUY/SELL below is a one-candle close-vs-open directional observation, NOT a certified Kronos strategy signal or instruction to trade."}),
  s.jsxs("div",{className:"v7-form-grid",children:[
   s.jsxs("label",{children:["Broker",s.jsx("select",{value:broker,onChange:e=>{const b=e.target.value;setBroker(b);setSymbol(groups[b][0])},
    children:Object.keys(groups).map(x=>s.jsx("option",{value:x,children:x},x))})]}),
   s.jsxs("label",{children:["Symbol",s.jsx("select",{value:symbol,onChange:e=>setSymbol(e.target.value),
    children:groups[broker].map(x=>s.jsx("option",{value:x,children:x},x))})]})
  ]}),
  s.jsx("p",{role:"status",className:"v7-info-status",children:broker!=="Deriv"?
    "Broker-native candle feed not connected for "+broker+". No signals can be shown.":
    feedState==="verified"?"DERIV LIVE CLOSED-CANDLE DATA · RESEARCH ONLY · AUTOMATED TRADING OFF":
    feedState==="loading"?"Loading real closed candles from Deriv…":"Broker closed-candle feed unavailable. No prices are invented."}),
  s.jsx("div",{className:"table-wrap",children:s.jsxs("table",{children:[
   s.jsx("thead",{children:s.jsx("tr",{children:["Timeframe","Candle bias (BUY/SELL)","Last CLOSED candle (UTC)","Open","Close","Next refresh"].map(x=>s.jsx("th",{children:x},x))})}),
   s.jsx("tbody",{children:V7_KRONOS_TF.map(tf=>{
    const r=broker==="Deriv"?candle(tf):null;
    return s.jsxs("tr",{children:[
      s.jsx("td",{children:tf}),
      s.jsx("td",{className:r?.candle_bias==="BUY"?"v7-signal-buy":r?.candle_bias==="SELL"?"v7-signal-sell":"subtle",children:r?.candle_bias||"—"}),
      s.jsx("td",{children:r?new Date(r.candle_closed_utc).toISOString().replace("T"," ").slice(0,19)+" UTC":"—"}),
      s.jsx("td",{children:r?Number(r.open).toLocaleString(undefined,{maximumFractionDigits:6}):"—"}),
      s.jsx("td",{children:r?Number(r.close).toLocaleString(undefined,{maximumFractionDigits:6}):"—"}),
      s.jsx("td",{className:"subtle",children:countdown(tf)})
    ]},tf)
   })})
  ]})}),
  report&&s.jsx("p",{className:"subtle",children:"Last refreshed "+new Date(report.checked_utc).toLocaleString()+". Source: Deriv public options market candles, not an MT5 account; all eight timeframes update when their broker candles close."}),
  s.jsx("p",{className:"subtle",children:"Kronos strategy certification: PENDING. Full multi-timeframe SMC/ICT fusion, execution confidence, slippage and profitable after-cost results are not established by the candle-direction indicator."})
 ]});
}

function V7CustomerProfile({token,customer}){
 const [data,setData]=zl.useState({phone:customer?.phone||"",physical_address:"",whatsapp_number:"",whatsapp_same_as_phone:false});
 const [status,setStatus]=zl.useState(""),[saving,setSaving]=zl.useState(false),[prop,setProp]=zl.useState(false);
 zl.useEffect(()=>{
  let active=true;
  fetch("/api/v1/me/profile",{headers:{Authorization:"Bearer "+token},cache:"no-store"})
   .then(r=>{if(!r.ok)throw Error("PROFILE_UNAVAILABLE");return r.json()})
   .then(v=>{if(active)setData({phone:v.phone||"",physical_address:v.physical_address||"",whatsapp_number:v.whatsapp_number||"",whatsapp_same_as_phone:v.whatsapp_same_as_phone===true})})
   .catch(()=>{if(active)setStatus("Profile updates unavailable; existing details were not changed.")});
  fetch("/api/v1/prop/overview",{headers:{Authorization:"Bearer "+token},cache:"no-store"})
   .then(r=>r.ok?r.json():null).then(v=>{if(active)setProp(v?.source==="EXTERNAL_VERIFIED_PROP_RECORDS"&&v?.count>0)})
   .catch(()=>{});
  return()=>{active=false}
 },[token]);
 function update(key,val){setData(old=>({...old,[key]:val,...(key==="phone"&&old.whatsapp_same_as_phone?{whatsapp_number:val}:{})}))}
 async function save(e){
  e.preventDefault();setSaving(true);setStatus("");
  try{
   const payload={...data,whatsapp_number:data.whatsapp_same_as_phone?data.phone:data.whatsapp_number};
   const r=await fetch("/api/v1/me/profile",{method:"PUT",headers:{"Content-Type":"application/json",Authorization:"Bearer "+token},body:JSON.stringify(payload)});
   if(!r.ok)throw Error("PROFILE_SAVE_REJECTED_"+r.status);
   const p=await r.json();
   setData({phone:p.phone||"",physical_address:p.physical_address||"",whatsapp_number:p.whatsapp_number||"",whatsapp_same_as_phone:p.whatsapp_same_as_phone===true});
   setStatus("Profile details saved securely.");
  }catch{setStatus("Profile update not available; no change was confirmed.")}
  finally{setSaving(false)}
 }
 return s.jsxs(s.Fragment,{children:[
  s.jsxs("section",{className:"panel",children:[
   s.jsxs("div",{className:"v7-section-heading",children:[s.jsx("h2",{children:"Customer Profile"}),s.jsx(V7GoldIcon,{name:"profile"})]}),
   s.jsx("p",{className:"subtle",children:"Signed in as "+(customer?.email||"customer")+". Contact details are stored against your authenticated customer account."}),
   s.jsxs("form",{onSubmit:save,children:[
    s.jsxs("div",{className:"v7-form-grid",children:[
      s.jsxs("label",{children:["Physical address",s.jsx("textarea",{value:data.physical_address,rows:3,maxLength:400,
         onChange:e=>update("physical_address",e.target.value),placeholder:"Street address, suburb, city, province, postal code"})]}),
      s.jsxs("label",{children:["Telephone number",s.jsx("input",{type:"tel",autoComplete:"tel",value:data.phone,maxLength:50,onChange:e=>update("phone",e.target.value)})]}),
      s.jsxs("label",{children:["WhatsApp number",s.jsx("input",{type:"tel",autoComplete:"off",value:data.whatsapp_same_as_phone?data.phone:data.whatsapp_number,
        maxLength:50,disabled:data.whatsapp_same_as_phone,onChange:e=>update("whatsapp_number",e.target.value)})]}),
      s.jsxs("label",{className:"v7-checkbox-line",children:[s.jsx("input",{type:"checkbox",checked:data.whatsapp_same_as_phone,
        onChange:e=>setData(old=>({...old,whatsapp_same_as_phone:e.target.checked,whatsapp_number:e.target.checked?old.phone:old.whatsapp_number}))}),
        " WhatsApp is the same as my telephone number"]})
    ]}),
    s.jsx("button",{className:"gold-button",type:"submit",disabled:saving,children:saving?"Saving…":"Save Profile"}),
    status&&s.jsx("p",{role:"status",className:"v7-info-status",children:status})
   ]})
  ]}),
  s.jsxs("section",{className:"panel",children:[
   s.jsx("h2",{children:"Banking details · Prop Firm packages only"}),
   s.jsx("p",{className:"subtle",children:prop?"A verified Prop Firm record is present. Bank-details collection requires the dedicated protected payout/KYC workflow.":"Only customers with a verified Abutron Prop Firm package are eligible to add payout bank details."}),
   s.jsx("div",{className:"v7-form-grid",children:["Account holder name","Bank name","Bank account number","Branch code","Account type"].map(k=>s.jsxs("label",{children:[k,s.jsx("input",{type:"text",disabled:true,placeholder:prop?"Protected payout verification pending":"Prop Firm package required",autoComplete:"off"})]},k))}),
   s.jsx("p",{className:"subtle",children:"Bank credentials are not collected, transmitted or stored through this general profile form."})
  ]})
 ]});
}

